/* XLSX and CSV processing stays in the browser. JSZip is bundled locally. */
const ExcelIO=(()=>{
 const xml=s=>{const d=new DOMParser().parseFromString(s,'application/xml');if(d.getElementsByTagName('parsererror').length)throw Error('Excel文件中的表格内容无法解析');return d},els=(e,n)=>Array.from(e.getElementsByTagNameNS('*',n)),text=(e,n)=>els(e,n).map(t=>t.textContent).join(''),escape=s=>String(s??'').replace(/[<>&"']/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[c]));
 const col=n=>{let s='';for(n++;n;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s};
 function parseCSV(s){s=s.replace(/^\uFEFF/,'');const rows=[];let row=[],v='',q=false;for(let i=0;i<s.length;i++){const c=s[i];if(c==='"'){if(q&&s[i+1]==='"'){v+='"';i++}else q=!q}else if(c===','&&!q){row.push(v);v=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&s[i+1]==='\n')i++;row.push(v);rows.push(row);row=[];v=''}else v+=c}if(q)throw Error('CSV的引号不完整');if(v||row.length){row.push(v);rows.push(row)}return rows.map((cells,i)=>({number:i+1,cells,hidden:false}))}
 async function read(file){if(file.size>25*1024*1024)throw Error('文件超过25MB，请仅保留需要结算的工作表后重新上传');if(/\.csv$/i.test(file.name)){let bytes=await file.arrayBuffer(),s=new TextDecoder('utf-8').decode(bytes);if(s.includes('\uFFFD'))s=new TextDecoder('gb18030').decode(bytes);return [{name:file.name,rows:parseCSV(s),hidden:false}]}
 if(!/\.xlsx$/i.test(file.name))throw Error('目前支持 .xlsx 和 .csv；请将旧版 .xls 另存为 .xlsx');const zip=await JSZip.loadAsync(await file.arrayBuffer());async function get(p){let f=zip.file(p);if(!f)throw Error('缺少Excel工作表：'+p);const s=await f.async('string');if(s.length>40*1024*1024)throw Error('工作表内容过大，请拆分后导入');return xml(s)}
 const book=await get('xl/workbook.xml'),rels=await get('xl/_rels/workbook.xml.rels');const targets=Object.fromEntries(els(rels,'Relationship').map(r=>[r.getAttribute('Id'),r.getAttribute('Target')]));let strings=[];if(zip.file('xl/sharedStrings.xml'))strings=els(await get('xl/sharedStrings.xml'),'si').map(x=>text(x,'t'));
 const sheets=[];for(const sh of els(book,'sheet')){const id=sh.getAttribute('r:id')||sh.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id');let target=targets[id];if(!target)continue;let path=target.startsWith('/')?target.slice(1):'xl/'+target;const stack=[];for(const p of path.split('/')){if(p==='..')stack.pop();else if(p!=='.')stack.push(p)}path=stack.join('/');const doc=await get(path);let rows=[];for(const r of els(doc,'row')){const cells=[];for(const c of els(r,'c')){const ref=c.getAttribute('r')||'';const letters=ref.match(/^[A-Z]+/);if(!letters)continue;let n=0;for(const l of letters[0])n=n*26+l.charCodeAt(0)-64;n--;if(n>2000)continue;const t=c.getAttribute('t'),raw=text(c,'v');cells[n]=t==='s'?(strings[Number(raw)]??''):t==='inlineStr'?text(c,'t'):t==='b'?(raw==='1'?'是':'否'):t==='e'?'[公式错误:'+raw+']':raw===''?'':t==='str'?raw:Number.isFinite(Number(raw))?Number(raw):raw}rows.push({number:Number(r.getAttribute('r'))||rows.length+1,cells,hidden:r.getAttribute('hidden')==='1'||r.getAttribute('hidden')==='true'})}if(rows.length>50000)throw Error('单张表超过5万行，请先筛选并删除不需要的行');sheets.push({name:sh.getAttribute('name'),rows,hidden:['hidden','veryHidden'].includes(sh.getAttribute('state'))})}return sheets}
 async function write(sheets){const zip=new JSZip();zip.file('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>'+sheets.map((_,i)=>`<Override PartName="/xl/worksheets/sheet${i+1}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join('')+'</Types>');zip.file('_rels/.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>');zip.file('xl/workbook.xml','<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets>'+sheets.map((s,i)=>`<sheet name="${escape(s.name)}" sheetId="${i+1}" r:id="rId${i+1}"/>`).join('')+'</sheets></workbook>');zip.file('xl/_rels/workbook.xml.rels','<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'+sheets.map((_,i)=>`<Relationship Id="rId${i+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${i+1}.xml"/>`).join('')+`<Relationship Id="rId${sheets.length+1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/></Relationships>`);
 zip.file('xl/styles.xml','<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><fonts count="2"><font><sz val="11"/><name val="Microsoft YaHei"/></font><font><b/><color rgb="FFFFFFFF"/><sz val="11"/><name val="Microsoft YaHei"/></font></fonts><fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FF20664E"/></patternFill></fill></fills><borders count="1"><border/></borders><cellStyleXfs count="1"><xf/></cellStyleXfs><cellXfs count="3"><xf fontId="0" fillId="0" borderId="0" xfId="0"/><xf fontId="1" fillId="2" borderId="0" xfId="0" applyFont="1" applyFill="1"><alignment vertical="center" wrapText="1"/></xf><xf numFmtId="4" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/></cellXfs></styleSheet>');
 sheets.forEach((s,i)=>{const width=s.rows.reduce((n,r)=>Math.max(n,r.length),1),end=col(width-1)+Math.max(s.rows.length,1);zip.file(`xl/worksheets/sheet${i+1}.xml`,'<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><dimension ref="A1:'+end+'"/><sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" state="frozen"/></sheetView></sheetViews><cols>'+Array.from({length:width},(_,j)=>`<col min="${j+1}" max="${j+1}" width="${s.widths?.[j]||22}" customWidth="1"/>`).join('')+'</cols><sheetData>'+s.rows.map((row,r)=>`<row r="${r+1}"${r===0?' ht="34" customHeight="1"':''}>`+row.map((v,c)=>typeof v==='number'&&Number.isFinite(v)?`<c r="${col(c)}${r+1}" s="${r===0?1:2}"><v>${v}</v></c>`:`<c r="${col(c)}${r+1}" s="${r===0?1:0}" t="inlineStr"><is><t xml:space="preserve">${escape(v)}</t></is></c>`).join('')+'</row>').join('')+'</sheetData><autoFilter ref="A1:'+end+'"/></worksheet>')});return zip.generateAsync({type:'blob',compression:'DEFLATE'})}
 return {read,write,parseCSV,col};
})();
